from pathlib import Path
from email.utils import parsedate_to_datetime
from datetime import datetime, timezone, timedelta
import xml.etree.ElementTree as ET
import html, re

out=Path('/tmp/crypto-research-20260521-131248')
now=datetime(2026,5,21,13,12,tzinfo=timezone.utc)
cut=now-timedelta(hours=24)

def strip_html(s):
    s=html.unescape(s or '')
    s=re.sub(r'<[^>]+>',' ',s)
    return re.sub(r'\s+',' ',s).strip()

def local(tag):
    return tag.split('}',1)[-1]

def parse_file(path, source):
    txt=path.read_text(errors='ignore')
    if '<rss' not in txt and '<feed' not in txt:
        return []
    try:
        root=ET.fromstring(txt)
    except Exception as e:
        print('PARSE_FAIL', source, e)
        return []
    items=[]
    for el in root.iter():
        if local(el.tag) not in ('item','entry'):
            continue
        data={}
        links=[]
        for child in list(el):
            k=local(child.tag)
            txt=(child.text or '').strip()
            if k=='link':
                href=child.attrib.get('href','').strip()
                if href: links.append(href)
                elif txt: links.append(txt)
            else:
                if txt and k not in data:
                    data[k]=txt
        title=data.get('title','')
        link=links[0] if links else ''
        desc=data.get('description') or data.get('summary') or data.get('encoded') or data.get('content') or ''
        pub=data.get('pubDate') or data.get('published') or data.get('updated') or ''
        dt=None
        if pub:
            for cand in [pub]:
                try:
                    dt=parsedate_to_datetime(cand)
                    break
                except Exception:
                    try:
                        dt=datetime.fromisoformat(cand.replace('Z','+00:00'))
                        break
                    except Exception:
                        pass
        if dt and not dt.tzinfo:
            dt=dt.replace(tzinfo=timezone.utc)
        items.append((source,dt,title,link,strip_html(desc)))
    return items

files=[('coindesk.xml','CoinDesk'),('cointelegraph.xml','CoinTelegraph'),('decrypt.xml','Decrypt'),('google.xml','Google News'),('beincrypto.xml','BeInCrypto'),('cryptoslate.xml','CryptoSlate'),('cryptofox-markets.xml','CryptoFox Markets'),('cryptofox-regulation.xml','CryptoFox Regulation')]
all=[]
for fn,src in files:
    all.extend(parse_file(out/fn,src))
recent=[x for x in all if x[1] and x[1]>=cut]
recent.sort(key=lambda x:(x[1],x[0]), reverse=True)
for src,dt,title,link,desc in recent[:180]:
    print(f'[{src}] {dt.isoformat()} | {title}\nURL: {link}\nDESC: {desc[:220]}\n')
print('TOTAL recent',len(recent))
